const levels: Cefr[] = ["A2", "B1", "B2", "C1"];
const bands = [3.5, 4.5, 5.5, 6.5];
export const expandedPlacementBank: (PlacementItem & { source: "ai"; quality: "ai-unreviewed" })[] = levels.flatMap((cefr, level) => (["reading", "listening"] as const).flatMap((skill) => {
  const block = (skill === "reading" ? reading : listeningPlacementRows)[cefr];
  return block.trim().split("\n").map((row, serial) => {
    const [text, question, answer, d1, d2, d3, explanation] = row.split("|");
    if (![text, question, answer, d1, d2, d3, explanation].every(Boolean)) throw new Error(`Invalid placement row ${skill}/${cefr}/${serial}`);
    const alternatives = [answer!, d1!, d2!, d3!];
    const offset = (serial + level + (skill === "reading" ? 0 : 1)) % 4;
    return { id: `placement-v3-${skill[0]}-${cefr.toLowerCase()}-${String(serial + 1).padStart(2, "0")}`, skill, text: text!, question: question!, answer: answer!, options: [...alternatives.slice(offset), ...alternatives.slice(0, offset)], explanation: explanation!, band: bands[level]!, cefr, difficulty: (bands[level]! - 5) * 1.2, subskill: level < 2 ? (skill === "listening" ? "detail-and-correction" : "detail-and-purpose") : "inference-and-evidence-limits", source: "ai", quality: "ai-unreviewed" };
  });
}));
